class Solution{void f(char[][]b,int i,int j){if(i<0||j<0||i==b.length||j==b[0].length||b[i][j]!='O')return;b[i][j]='#';f(b,i+1,j);f(b,i-1,j);f(b,i,j+1);f(b,i,j-1);}public void solve(char[][]b){if(b.length==0)return;int m=b.length,n=b[0].length;for(int i=0;i<m;i++){f(b,i,0);f(b,i,n-1);}for(int j=0;j<n;j++){f(b,0,j);f(b,m-1,j);}for(int i=0;i<m;i++)for(int j=0;j<n;j++)b[i][j]=b[i][j]=='#'?'O':b[i][j]=='O'?'X':b[i][j];}}
